basicCode.vanilla:
import { createCostMeter } from '@/components/ui/cost-meter';

createCostMeter({
  amount: quantia,
  budget: teto,
  labels: rotulos,
});

withLabelsCode.web:
// O DINHEIRO CHEGA ESCRITO. Símbolo, posição do símbolo, separador de milhar,
// separador decimal e número de casas variam por idioma E por moeda — a mesma
// quantia sai `US$ 0,84`, `$0.84` ou `0,84 US$` conforme quem lê. Quem sabe
// disso é quem escolheu a moeda.
const money = new Intl.NumberFormat('pt-BR', {
  style: 'currency',
  currency: 'USD',
});

const quantia = money.format(0.84);

// O teto anda em par: a quantia ESCRITA e a fração JÁ CALCULADA. A fração é
// número puro — não tem moeda nem idioma —, e é ela que entra na conta.
// Sem teto declarado, a fração sai como ausência e o par inteiro não é passado.
const teto = { amount: money.format(1), fraction: spentFraction(0.84, 1) };

// E o texto da peça: o nome da medida, a palavra de cada nível, a ligação
// entre a fração e o teto, e o que dizer quando não há teto.
const rotulos = {
  title: 'Custo desta execução',
  level: { normal: 'Com folga', warning: 'Perto do teto', critical: 'No teto' },
  of: 'de',
  unbounded: 'Sem teto declarado',
};

extensibilityCode.web:
// SEM TETO NÃO HÁ FRAÇÃO. Teto ausente, zero ou não-finito são a mesma resposta:
spentFraction(0.84);           // null
spentFraction(0.84, 0);        // null
spentFraction(0.84, 1);        // 0.84

// RECORTADA EM UMA VOLTA: uma barra não passa do trilho, e desenhar 1,24
// desenharia 1 de qualquer jeito — só que sem ninguém ter escolhido.
spentFraction(1.24, 1);        // 1

// O LIMIAR É O MESMO DA MEDIÇÃO DA JANELA, e é exato — três quartos já é aviso:
fractionLevel(0.74);           // 'normal'
fractionLevel(0.75);           // 'warning'
fractionLevel(0.9);            // 'critical'

// E o por cento é TEXTO, travado nas duas pontas, porque é ele que se lê em voz:
fractionPercent(0.999);        // 99
fractionPercent(1);            // 100
fractionPercent(null);         // null

customizationCode.web:
.nds-cost-meter {
  max-inline-size: 24rem;
}

/* O medidor é REFORÇO, e não a pista: a palavra do nível e o por cento ao lado
   são o que descreve. Mexer na cor não muda o que chega a quem ouve. */
.nds-cost-meter[data-level="warning"] {
  --nds-cost-meter-color: var(--chart-4);
}

